contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, bytes32 b1, bytes32 b2, bytes calldata bs, uint256 utxoSize, uint256 fee) public payable {
        require(target != address(0));
        // sample read of approved status before any state-changing call
        bool beforeTargetApproved = c.approvedToLog(target); if (__ESBMC_reverted()) return;
        // Also check some other random address (this contract) approved status
        bool beforeThisApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // Make a state-changing call from this contract: attempt to logRegisteredPubkey
        // The behavior should depend only on approvedToLog(msg.sender) where msg.sender is this contract
        bool reverted;
        bool ret;
        bool r = c.logRegisteredPubkey(b1, b2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            ret = false;
        } else {
            reverted = false;
            ret = r;
        }

        // After the call, the approved status for arbitrary addresses (including target and this contract)
        // must remain unchanged because none of the log... functions modify approvedLoggers mapping.
        bool afterTargetApproved = c.approvedToLog(target); if (__ESBMC_reverted()) return;
        bool afterThisApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // The general rule: the call must not revert, and its boolean return must equal the approval status of the caller at call-time
        // OR if it reverted then it must be because of some internal reason; however these functions do not revert on approval checks
        // so we assert that the call did not revert, its return equals the prior approval for this contract,
        // and approvedLoggers for any observed addresses are unchanged.
        assert(reverted == false && ret == beforeThisApproved && afterTargetApproved == beforeTargetApproved && afterThisApproved == beforeThisApproved);
    }
    receive() external payable {}
}

