pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address target, bytes32 b1, bytes32 b2, bytes memory bs, uint256 utxoSize, uint256 fee) internal {
        vm.assume(target != address(0));
        bool beforeTargetApproved;
        try c.approvedToLog(target) returns (bool __r) { beforeTargetApproved = __r; } catch { return; }
        bool beforeThisApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeThisApproved = __r; } catch { return; }
        bool reverted;
        bool ret;
        try c.logRegisteredPubkey(b1, b2) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        bool afterTargetApproved;
        try c.approvedToLog(target) returns (bool __r) { afterTargetApproved = __r; } catch { return; }
        bool afterThisApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { afterThisApproved = __r; } catch { return; }
        assertTrue(reverted == false && ret == beforeThisApproved && afterTargetApproved == beforeTargetApproved && afterThisApproved == beforeThisApproved);
    }

    function testFuzz_run(address target, bytes32 b1, bytes32 b2, bytes memory bs, uint256 utxoSize, uint256 fee) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, b1, b2, bs, utxoSize, fee);
    }

    receive() external payable {}
}
